# ══════════════════════════════════════════════════════
#  PARSER
# ══════════════════════════════════════════════════════
def detect_color(text):
    if not text or not text.strip(): return "unknown"
    t = text.lower().strip()
    import re
    for c in sorted(COLORS_LIST, key=len, reverse=True):
        if re.search(r"\b" + re.escape(c) + r"\b", t): return c
    return "unknown"


def detect_item(text):
    if not text or not text.strip(): return None
    t = text.lower().strip()
    import re
    # Match longest exact phrase first with word boundaries
    for item in sorted(ALL_ITEMS, key=len, reverse=True):
        if re.search(r"\b" + re.escape(item) + r"\b", t):
            return item
    # Fallback to fuzzy match on individual words
    for token in t.split():
        close = get_close_matches(token, ALL_ITEMS, n=1, cutoff=0.78)
        if close: return close[0]
    return None


def item_category(item):
    if not item: return "unknown"
    if item in FULL_WORDS:   return "full"
    if item in BOTTOM_WORDS: return "bottom"
    return "top"

def top_sub_key(item):
    mapping = {
        "t-shirt":"tshirt","graphic tee":"tshirt","tank top":"top","camisole":"top",
        "tunic":"top","overshirt":"shirt","henley":"shirt","linen shirt":"shirt",
        "turtleneck":"sweater","cardigan":"sweater","sweatshirt":"hoodie",
        "nehru jacket":"jacket","coat":"jacket","vest":"blazer","polo":"shirt",
    }
    return mapping.get(item, item if item in F_TOP_TO_BOT else "other")

def bot_sub_key(item):
    mapping = {
        "trousers":"trousers","pants":"trousers","chinos":"chinos",
        "track pants":"track pants","joggers":"track pants","sweatpants":"track pants",
        "cargo pants":"shorts","leggings":"leggings","salwar":"salwar",
        "churidar":"churidar","dhoti":"churidar","kurta pajama":"churidar",
        "lehenga skirt":"lehenga skirt","mini skirt":"skirt","pencil skirt":"skirt","wrap skirt":"skirt",
    }
    return mapping.get(item, item if item in F_BOT_TO_TOP else "other")

def detect_occasion(text):
    t = text.lower()
    for occ, words in OCCASION_MAP.items():
        if any(w in t for w in words): return occ
    return "casual"

def check_mismatch(item, gender):
    if not item: return False, ""
    il = item.lower().strip()
    if gender == "male":
        for fi in FEMALE_ONLY:
            if fi in il or il in fi:
                return True, f"<b>{item.title()}</b> is a female garment. Please switch gender to <b>Female</b> or enter a different item."
    if gender == "female":
        for mi in MALE_ONLY:
            if mi in il or il in mi:
                return True, f"<b>{item.title()}</b> is a male garment. Please switch gender to <b>Male</b> or enter a different item."
    return False, ""

# ══════════════════════════════════════════════════════
#  WARDROBE MATCH
# ══════════════════════════════════════════════════════
def ww_find(wardrobe, cat, gender, occasion, color=None, exclude_full_outfits=False):
    paired = [c.lower() for c in (TOP_TO_BOT_COLORS if cat=="bottom" else BOT_TO_TOP_COLORS).get(color or "unknown",[])]
    best, bs = None, -1
    for item in wardrobe:
        it = item.get("type","").lower()
        ig = item.get("gender","unisex").lower()
        ic = item.get("color","").lower()
        io = [o.lower() for o in item.get("occasions",[])]

        if cat == "top":
            if it not in ("top","outerwear"): continue
            if exclude_full_outfits and it == "dress": continue
        elif cat == "bottom"    and it != "bottom":    continue
        elif cat == "footwear"  and it != "footwear":  continue
        elif cat == "accessory" and it != "accessory": continue

        if ig not in (gender,"unisex"): continue
        score = 3 if ig==gender else 1
        if occasion in io: score += 2
        if ic in paired:   score += 1
        if score > bs: bs=score; best=item["name"]
    return best

# ══════════════════════════════════════════════════════
#  OUTFIT BUILDER
# ══════════════════════════════════════════════════════
def build_outfit(top_input, bot_input, gender, occasion, wardrobe):
    color_top = detect_color(top_input) if top_input.strip()  else "unknown"
    color_bot = detect_color(bot_input) if bot_input.strip()  else "unknown"
    item_top  = detect_item(top_input)  if top_input.strip()  else None
    item_bot  = detect_item(bot_input)  if bot_input.strip()  else None

    has_top = bool(top_input.strip())
    has_bot = bool(bot_input.strip())
    both    = has_top and has_bot
    result  = {}

    if both:
        top_label = f"{color_top.title()+' ' if color_top!='unknown' else ''}{item_top.title() if item_top else top_input.title()}"
        bot_label = f"{color_bot.title()+' ' if color_bot!='unknown' else ''}{item_bot.title() if item_bot else bot_input.title()}"
        result.update(mode="both",top_name=top_label,bot_name=bot_label,
                      top_src="input",bot_src="input",color_hint=[],hint_label="")
        active_color = color_top if color_top!="unknown" else color_bot

    elif has_top:
        cat = item_category(item_top) if item_top else "top"
        top_label = f"{color_top.title()+' ' if color_top!='unknown' else ''}{item_top.title() if item_top else top_input.title()}"
        if cat == "full":
            result.update(mode="full_top",top_name=top_label,
                          bot_name="(Complete outfit — no bottom needed)",
                          top_src="input",bot_src="rule",color_hint=[],hint_label="")
        else:
            sk  = top_sub_key(item_top) if item_top else "other"
            bot = (F_TOP_TO_BOT if gender=="female" else M_TOP_TO_BOT).get(sk, F_TOP_TO_BOT["other"]).get(occasion,"Jeans")
            ww_bot = ww_find(wardrobe,"bottom",gender,occasion,color_top)
            result.update(mode="top",top_name=top_label,
                          bot_name=ww_bot if ww_bot else bot,
                          top_src="input",bot_src="wardrobe" if ww_bot else "rule",
                          color_hint=TOP_TO_BOT_COLORS.get(color_top,TOP_TO_BOT_COLORS["unknown"])[:4],
                          hint_label="Best bottom colours for your top")
        active_color = color_top

    else:
        bot_label = f"{color_bot.title()+' ' if color_bot!='unknown' else ''}{item_bot.title() if item_bot else bot_input.title()}"
        sk  = bot_sub_key(item_bot) if item_bot else "other"
        top = (F_BOT_TO_TOP if gender=="female" else M_BOT_TO_TOP).get(sk, F_BOT_TO_TOP["other"]).get(occasion,"Casual Top")
        ww_top = ww_find(wardrobe,"top",gender,occasion,color_bot,exclude_full_outfits=True)
        result.update(mode="bottom",top_name=ww_top if ww_top else top,
                      bot_name=bot_label,
                      top_src="wardrobe" if ww_top else "rule",bot_src="input",
                      color_hint=BOT_TO_TOP_COLORS.get(color_bot,BOT_TO_TOP_COLORS["unknown"])[:4],
                      hint_label="Best top colours for your bottom")
        active_color = color_bot

    ww_shoe = ww_find(wardrobe,"footwear",gender,occasion,active_color)
    shoe_rule, shoe_emoji = (F_SHOE if gender=="female" else M_SHOE)[occasion]
    result["shoe_name"] = ww_shoe if ww_shoe else f"{shoe_emoji} {shoe_rule}"
    result["shoe_src"]  = "wardrobe" if ww_shoe else "rule"

    ww_acc    = ww_find(wardrobe,"accessory",gender,occasion,active_color)
    acc_rules = (F_ACC if gender=="female" else M_ACC)[occasion]
    if ww_acc:
        result["acc_list"] = [(ww_acc,"💍"), acc_rules[1]]
        result["acc_src"]  = "wardrobe"
    else:
        result["acc_list"] = acc_rules
        result["acc_src"]  = "rule"

    result["hair"] = (F_HAIR if gender=="female" else M_HAIR)[occasion]
    result["tip"]  = (F_TIPS if gender=="female" else M_TIPS)[occasion]
    return result

